/* =================================
   Mobile
   ================================= */

@media (max-width: 640px) {
  .sidebar-backdrop {
    display: block;
  }

  .sidebar-toggle {
    display: inline-block;
  }

  .sidebar {
    position: fixed;
    top: 0;
    left: 0;
    z-index: 50;
    height: 100vh;
    transform: translateX(-100%);
    box-shadow: 8px 0 40px rgba(0, 0, 0, 0.12);
  }

  .sidebar.open {
    transform: translateX(0);
  }

  .chat-layout {
    flex-direction: column;
  }

  .header {
    flex-wrap: wrap;
    padding: 0.65rem 1rem;
  }

  .header .status {
    max-width: 100%;
  }

  .composer {
    padding: 0.75rem 1rem 0.9rem;
  }

  .messages {
    padding: 1rem;
  }

  .msg {
    max-width: 96%;
  }

  .connect-hero .logo-symbol {
    width: 44px;
    height: 44px;
    font-size: 1.3rem;
  }

  .connect-panel {
    padding: 1.5rem;
  }
}

