				const statusLabel = failed ? "failed" : "completed";
				await this.recordRoleMessage("hub_role_output", `[${role.name}] (${statusLabel})\nTask: ${task.task}\n\n${runResult.output}`, { role: role.name, taskId, task: task.task, exitCode: runResult.exitCode });

