			const statusLabel = failed ? "failed" : "completed";
			await this.recordRoleMessage("hub_role_output", `[${role.name}] (${statusLabel})\n\n${runResult.output}`, { role: role.name, taskId, exitCode: runResult.exitCode });

			results.push({ role: role.name, task: userMessage, taskId, exitCode: runResult.exitCode, output: runResult.output, errorMessage: runResult.errorMessage } satisfies RoleTaskResult);
		}

		if (results.length === 1) {
			const r = results[0]!;
			if (r.exitCode === 0) {
				await this.session.prompt(r.output, { source: "rpc" });
			}
		} else {
			const sections = results.map((r) => `### Role: ${r.role} (${r.exitCode === 0 ? "completed" : "failed"})\n\n${r.output}`);
			const combined = `[Multi-role direct responses]\n\nOriginal request:\n${userMessage}\n\n${sections.join("\n\n---\n\n")}`;
			await this.session.prompt(combined, { source: "rpc" });
		}
	}
}

